WITH subq1 AS ( WITH inner_cte AS ( SELECT t1.FULL_NAME, t1.EMAIL_ADDRESS, t0.DEPARTMENT_FULL_NAME, t0.DEPARTMENT_CODE FROM SIS_DEPARTMENT t0 JOIN MIT_STUDENT_DIRECTORY t1 ON t0.DEPARTMENT_CODE = t1.DEPARTMENT WHERE t0.IS_DEGREE_GRANTING = 'Y' AND t1.STUDENT_YEAR = 'G' ) SELECT i.FULL_NAME, i.EMAIL_ADDRESS, i.DEPARTMENT_FULL_NAME, i.DEPARTMENT_CODE, (LENGTH(i.FULL_NAME) - avg_len.avg_full_name_length) AS diff_from_avg_length FROM inner_cte i JOIN ( SELECT AVG(LENGTH(FULL_NAME)) AS avg_full_name_length FROM inner_cte ) avg_len ON 1=1 ), subq2 AS ( WITH inner_cte AS ( SELECT lso.NUM_ENROLLED_STUDENTS, sos.TOTAL_UNITS, lso.OFFER_SCHOOL_NAME, sos.OFFER_DEPT_CODE FROM LIBRARY_SUBJECT_OFFERED lso JOIN TIP_DETAIL td ON lso.SUBJECT_ID = td.SUBJECT_ID JOIN SUBJECT_OFFERED_SUMMARY sos ON td.SUBJECT_ID = sos.SUBJECT_ID WHERE td.TIP_MATERIAL_STATUS_KEY = 'RQ' ) SELECT OFFER_SCHOOL_NAME, OFFER_DEPT_CODE, MIN(NUM_ENROLLED_STUDENTS) AS min_enrolled_students, SUM(TOTAL_UNITS) AS total_units FROM inner_cte GROUP BY OFFER_SCHOOL_NAME, OFFER_DEPT_CODE WITH ROLLUP HAVING SUM(TOTAL_UNITS) > 0 ) SELECT s1.FULL_NAME, s1.EMAIL_ADDRESS, s1.DEPARTMENT_FULL_NAME, s1.diff_from_avg_length, s2.OFFER_SCHOOL_NAME, s2.min_enrolled_students, s2.total_units FROM subq1 s1 JOIN subq2 s2 ON s1.DEPARTMENT_CODE = s2.OFFER_DEPT_CODE ORDER BY s1.FULL_NAME, s2.OFFER_SCHOOL_NAME